mapper.select:
SELECT u.user_no,i.provider_uid,u.nickname,u.avatar_url,p.preferred_avatar_id,p.preferred_voice,p.subtitle_enabled,p.translation_mode
FROM app_user u JOIN user_identity i ON i.user_id=u.id AND i.provider='account' AND i.deleted_at IS NULL
JOIN user_profile p ON p.user_id=u.id WHERE u.id=#{userId}
